type OperationKind = "purchases" | "sales" | "adjustments" | "transfers" | "expenses" | "payments" | "stock-report";
type RelatedRecord = { id?: string; code?: string; name?: string; sku?: string; fullName?: string; minStock?: number; unit?: { code?: string }; trackBatch?: boolean };
type OperationItem = { product?: RelatedRecord; quantity?: number; receivedQuantity?: number; total?: number | string; batchNumber?: string | null; expiryDate?: string | null; productionDate?: string | null };
type OperationRecord = {
  id: string; number?: string; status?: string; type?: string; category?: string; method?: string;
  isPaid?: boolean; isLowStock?: boolean; quantityOnHand?: number | string; reservedQuantity?: number | string; availableQuantity?: number | string; total?: number | string;
  amount?: number | string; orderDate?: string; saleDate?: string; adjustmentDate?: string;
  transferDate?: string; expenseDate?: string; paymentDate?: string; createdAt?: string;
  notes?: string | null; reason?: string; description?: string | null; supplier?: RelatedRecord;
  customer?: RelatedRecord; fromWarehouse?: RelatedRecord; toWarehouse?: RelatedRecord;
  warehouse?: RelatedRecord; product?: RelatedRecord; location?: RelatedRecord; purchaseOrder?: { number?: string };
  approvedAt?: string; approvedBy?: { fullName?: string }; createdBy?: RelatedRecord;
  sale?: { number?: string }; expense?: { number?: string }; items?: OperationItem[];
};
type PageMeta = { page: number; pageSize: number; total: number; totalPages: number };
type OptionRecord = { id: string; code?: string; name?: string; sku?: string; warehouseId?: string; productId?: string; batchNumber?: string; trackBatch?: boolean; product?: { sku?: string; name?: string } };
type OperationsOptions = { products: OptionRecord[]; warehouses: OptionRecord[]; suppliers: OptionRecord[]; customers: OptionRecord[]; purchaseOrders: OptionRecord[]; sales: OptionRecord[]; expenses: OptionRecord[]; locations: OptionRecord[]; batches: OptionRecord[] };
type FormState = Record<string, string>;
type ItemDraft = { key: string; productId: string; quantity: string; unitPrice: string; batchNumber: string; productionDate: string; expiryDate: string; locationId: string; batchId: string; sourceLocationId: string; destinationLocationId: string };

function newItemDraft(): ItemDraft { return { key: crypto.randomUUID(), productId: "", quantity: "1", unitPrice: "0", batchNumber: "", productionDate: "", expiryDate: "", locationId: "", batchId: "", sourceLocationId: "", destinationLocationId: "" }; }

