  adjustments: { title: "Penyesuaian stok", description: "Koreksi jumlah stok berdasarkan pemeriksaan fisik dan alasan yang jelas.", endpoint: "/api/operations/adjustments", permission: "adjustments.read", writePermission: "adjustments.write", deletePermission: "adjustments.delete", approvalPermission: "adjustments.approve", addLabel: "Buat penyesuaian", accent: "from-orange-500 to-amber-500", soft: "bg-orange-50 text-orange-700" },
