  const canApprove = Boolean(current.approvalPermission && can(current.approvalPermission));
  const [rows, setRows] = useState<OperationRecord[]>([]);
  const [pageState, setPageState] = useState<{ kind: OperationKind; value: number }>({ kind, value: 1 }); const page = pageState.kind === kind ? pageState.value : 1; const setPage = (value: number | ((previous: number) => number)) => setPageState((current) => ({ kind, value: typeof value === "function" ? value(current.kind === kind ? current.value : 1) : value }));
  const [meta, setMeta] = useState<PageMeta | null>(null);
  const [options, setOptions] = useState<OperationsOptions | null>(null);
  const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false);
  const [error, setError] = useState(""); const [search, setSearch] = useState(""); const [searchQuery, setSearchQuery] = useState(""); const [statusState, setStatusState] = useState<{ kind: OperationKind; value: string }>({ kind, value: "" }); const statusFilter = statusState.kind === kind ? statusState.value : ""; const setStatusFilter = (value: string) => setStatusState({ kind, value }); const [fromDate, setFromDate] = useState(""); const [toDate, setToDate] = useState("");
  const [formOpen, setFormOpen] = useState(false); const [editing, setEditing] = useState<OperationRecord | null>(null); const [receivingRow, setReceivingRow] = useState<OperationRecord | null>(null); const [form, setForm] = useState<FormState>(initialForm);
  const [lineItems, setLineItems] = useState<ItemDraft[]>([newItemDraft()]);
  const [notice, setNotice] = useState("");
  const [warehouseFilter, setWarehouseFilter] = useState(target?.page === "stock-report" ? target.warehouseId ?? "" : "");
  const [reportWarehouses, setReportWarehouses] = useState<OptionRecord[]>([]);
  const loadSequence = useRef(0);

  function refreshNotificationBell() { window.dispatchEvent(new Event("stockflow:notifications")); }

  useEffect(() => { const timer = window.setTimeout(() => setSearchQuery(search.trim()), 300); return () => window.clearTimeout(timer); }, [search]);
  useEffect(() => {
    if (!target || target.page !== kind) return;
    const timer = window.setTimeout(() => { setSearch(target.reference); setSearchQuery(target.reference); setStatusFilter(""); setFromDate(""); setToDate(""); setWarehouseFilter(target.warehouseId ?? ""); setPage(1); }, 0);
    return () => window.clearTimeout(timer);
  // The notification token changes whenever a destination is opened again.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [target?.token, kind]);
  useEffect(() => {
    if (kind !== "stock-report") return;
    const controller = new AbortController();
    void apiRequest<{ data: OptionRecord[] }>("/api/operations/report-warehouses", { signal: controller.signal }).then((response) => { if (!controller.signal.aborted) setReportWarehouses(response.data ?? []); }).catch(() => { if (!controller.signal.aborted) setError("Daftar gudang laporan tidak dapat dimuat."); });
    return () => controller.abort();
  }, [kind]);

  async function load() { const sequence = ++loadSequence.current; if (fromDate && toDate && fromDate > toDate) { setError("Tanggal awal harus sebelum atau sama dengan tanggal akhir."); setLoading(false); return; } setLoading(true); setError(""); try { const params = new URLSearchParams({ page: String(page), pageSize: "25" }); if (searchQuery) params.set("search", searchQuery); if (kind === "stock-report" && warehouseFilter) params.set("warehouseId", warehouseFilter); if (statusFilter) params.set("status", statusFilter); if (fromDate) params.set("fromDate", fromDate); if (toDate) params.set("toDate", toDate); const endpoint = `${current.endpoint}${current.endpoint.includes("?") ? "&" : "?"}${params}`; const response = await apiRequest<{ success: boolean; data?: OperationRecord[]; meta?: PageMeta; message?: string }>(endpoint); if (sequence === loadSequence.current) { setRows(response.data ?? []); setMeta(response.meta ?? null); } } catch (reason) { if (sequence === loadSequence.current) setError(reason instanceof Error ? reason.message : "Gagal memuat data. Coba lagi."); } finally { if (sequence === loadSequence.current) setLoading(false); } }
  async function loadOptions() { if (options || kind === "stock-report") return; try { const response = await apiRequest<{ success: boolean; data?: OperationsOptions }>("/api/operations/options"); setOptions(response.data ?? null); } catch (reason) { setError(reason instanceof Error ? reason.message : "Failed to load form options"); } }
  useEffect(() => { const timer = window.setTimeout(() => void load(), 0); return () => window.clearTimeout(timer); // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [current.endpoint, page, searchQuery, statusFilter, fromDate, toDate, warehouseFilter, kind]);
  const filtered = rows;
  const stats = useMemo(() => kind === "stock-report" ? [["Baris stok di halaman", rows.length], ["Stok rendah di halaman", rows.filter((row) => row.isLowStock).length], ["Unit di halaman", rows.reduce((sum, row) => sum + Number(row.quantityOnHand ?? 0), 0)]] : [["Catatan di halaman", rows.length], ["Aktif di halaman", rows.filter((row) => !["CANCELLED", "VOID"].includes(row.status ?? "")).length], ["Nilai di halaman", money(rows.reduce((sum, row) => sum + Number(row.total ?? row.amount ?? 0), 0))]], [kind, rows]);

  function openCreate() { setError(""); const prefix = kind === "purchases" ? "PO" : kind === "sales" ? "SO" : kind === "adjustments" ? "ADJ" : kind === "transfers" ? "TRF" : kind === "expenses" ? "EXP" : "PAY"; setEditing(null); setLineItems([newItemDraft()]); setForm({ ...initialForm, number: `${prefix}-${Date.now().toString().slice(-6)}`, status: kind === "payments" ? "PAID" : "DRAFT", type: kind === "payments" ? "PURCHASE" : kind === "adjustments" ? "INCREASE" : initialForm.type }); setFormOpen(true); void loadOptions(); }
  function openEdit(row: OperationRecord) { setError(""); setEditing(row); setForm({ ...initialForm, number: row.number ?? "", status: row.status ?? "DRAFT", notes: row.notes ?? "", category: row.category ?? "", description: row.description ?? "", amount: String(row.amount ?? "0"), method: row.method ?? "BANK_TRANSFER", isPaid: String(row.isPaid ?? false) }); setFormOpen(true); void loadOptions(); }
  function closeForm() { if (!saving) setFormOpen(false); }
  function updateField(field: string, value: string) { setForm((previous) => ({ ...previous, [field]: value })); }
  function updateLineItem(key: string, field: keyof Omit<ItemDraft, "key">, value: string) { setLineItems((items) => items.map((item) => item.key === key ? { ...item, [field]: value } : item)); }
  function createPayload(): Record<string, unknown> { const purchaseItems = lineItems.map((item) => ({ productId: item.productId, quantity: Number(item.quantity), unitPrice: Number(item.unitPrice), batchNumber: item.batchNumber || null, productionDate: item.productionDate || null, expiryDate: item.expiryDate || null })); const saleItems = lineItems.map((item) => ({ productId: item.productId, quantity: Number(item.quantity), unitPrice: Number(item.unitPrice) })); const adjustmentItems = lineItems.map((item) => ({ productId: item.productId, quantity: Number(item.quantity), locationId: item.locationId || null, batchId: item.batchId || null })); const transferItems = lineItems.map((item) => ({ productId: item.productId, quantity: Number(item.quantity), sourceLocationId: item.sourceLocationId || null, destinationLocationId: item.destinationLocationId || null, batchId: item.batchId || null })); if (kind === "purchases") return { number: form.number, supplierId: form.supplierId, warehouseId: form.warehouseId, status: form.status, tax: Number(form.tax), notes: form.notes || null, items: purchaseItems }; if (kind === "sales") return { number: form.number, customerId: form.customerId || null, warehouseId: form.warehouseId, status: form.status, discount: Number(form.discount), tax: Number(form.tax), notes: form.notes || null, items: saleItems }; if (kind === "adjustments") return { number: form.number, warehouseId: form.warehouseId, type: form.type, status: form.status, reason: form.reason, items: adjustmentItems }; if (kind === "transfers") return { number: form.number, fromWarehouseId: form.fromWarehouseId, toWarehouseId: form.toWarehouseId, status: form.status, notes: form.notes || null, items: transferItems }; if (kind === "expenses") return { number: form.number, category: form.category, description: form.description || null, amount: Number(form.amount), warehouseId: form.warehouseId || null, isPaid: form.isPaid === "true" }; return { number: form.number, type: form.type, amount: Number(form.amount), method: form.method, status: form.status, purchaseOrderId: form.type === "PURCHASE" ? form.relationId : null, saleId: form.type === "SALE" ? form.relationId : null, expenseId: form.type === "EXPENSE" ? form.relationId : null }; }
  function editPayload(): Record<string, unknown> { if (kind === "expenses") return { category: form.category, description: form.description || null, amount: Number(form.amount), isPaid: form.isPaid === "true" }; if (kind === "payments") return { method: form.method, status: form.status, notes: form.notes || null }; if (kind === "adjustments") return { status: form.status }; return { status: form.status, notes: form.notes || null }; }
  async function save() { if (!editing && kind === "purchases" && (!form.supplierId || !form.warehouseId)) { setError("Pilih supplier dan gudang penerima terlebih dahulu."); return; } if (!editing && kind === "sales" && !form.warehouseId) { setError("Pilih gudang pengeluaran terlebih dahulu."); return; } if (!editing && kind === "adjustments" && (!form.warehouseId || !form.reason.trim())) { setError("Pilih gudang dan isi alasan penyesuaian stok."); return; } if (!editing && kind === "transfers" && (!form.fromWarehouseId || !form.toWarehouseId)) { setError("Pilih gudang asal dan gudang tujuan."); return; } if (!editing && kind === "payments" && !form.relationId) { setError("Pilih transaksi yang akan dibayar."); return; } if (!editing && kind === "expenses" && !form.category.trim()) { setError("Isi kategori pengeluaran terlebih dahulu."); return; } if (!editing && ["purchases", "sales", "adjustments", "transfers"].includes(kind)) { if (lineItems.length === 0 || lineItems.some((item) => !item.productId || !Number.isInteger(Number(item.quantity)) || Number(item.quantity) < 1 || ((kind === "purchases" || kind === "sales") && (!Number.isFinite(Number(item.unitPrice)) || Number(item.unitPrice) < 0)))) { setError("Lengkapi produk, jumlah minimal 1, dan harga yang valid pada setiap baris."); return; } if (kind === "transfers" && form.fromWarehouseId === form.toWarehouseId) { setError("Gudang asal dan tujuan harus berbeda."); return; } } setSaving(true); setError(""); try { const endpoint = editing ? `${current.endpoint}/${editing.id}` : current.endpoint; const result = await apiRequest<{ success: boolean; message?: string }>(endpoint, { method: editing ? "PATCH" : "POST", body: JSON.stringify(editing ? editPayload() : createPayload()) }); if (!result.success) throw new Error(result.message ?? "Penyimpanan gagal"); setFormOpen(false); setNotice(editing ? "Perubahan berhasil disimpan." : "Transaksi berhasil dibuat."); await load(); refreshNotificationBell(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Penyimpanan gagal. Periksa data dan coba lagi."); } finally { setSaving(false); } }
  async function approve(row: OperationRecord) { setSaving(true); setError(""); try { const result = await apiRequest<{ success: boolean; message?: string }>(`${current.endpoint}/${row.id}/approve`, { method: "POST" }); if (!result.success) throw new Error(result.message ?? "Persetujuan gagal"); setNotice(`${row.number ?? "Transaksi"} berhasil disetujui.`); await load(); refreshNotificationBell(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Persetujuan gagal. Coba lagi."); } finally { setSaving(false); } }
